            if len(comp) == 1:
                singles.append(comp[0])
                continue
            counts = Counter(grid[r][c] for r, c in comp if grid[r][c] != bg)
            color = min(counts, key=lambda x: counts[x])
            points = [(r,c) for r,c in comp if grid[r][c] == color]
            pos[color] = (min(r for r,c in points), max(r for r,c in points),
                          min(c for r,c in points), max(c for r,c in points))
    kr = max(r for r,c in singles)
    order = [grid[kr][c] for c in range(w) if grid[kr][c] != bg]
    for color, target in zip(order, order[1:]):
        top, bottom, left, right = pos[color]
        ttop, tbottom, tleft, tright = pos[target]
        if right < tleft:
            rows = range(top, bottom+1)
            cols = range(right+1, tleft)
        elif tright < left:
            rows = range(top, bottom+1)
            cols = range(tright+1, left)
        elif bottom < ttop:
            rows = range(bottom+1, ttop)
            cols = range(left, right+1)
        else:
            rows = range(tbottom+1, top)
            cols = range(left, right+1)
        for r in rows:
            for c in cols:
                out[r][c] = color
    return out
